464	   * modules and children.
465	   */
466	  protected async callShutdownHook(signal?: string): Promise<void> {
467	    const modulesSortedByDistance = [
468	      ...this.getModulesToTriggerHooksOn(),
469	    ].reverse();
470	
471	    for (const module of modulesSortedByDistance) {
472	      await callAppShutdownHook(module, signal);
473	    }
474	  }
475	
476	  /**
477	   * Calls the `beforeApplicationShutdown` function on the registered
478	   * modules and children.
479	   */
480	  protected async callBeforeShutdownHook(signal?: string): Promise<void> {
481	    const modulesSortedByDistance = [
482	      ...this.getModulesToTriggerHooksOn(),
483	    ].reverse();
484	
485	    for (const module of modulesSortedByDistance) {
486	      await callBeforeAppShutdownHook(module, signal);
487	    }
488	  }
