490	  protected assertNotInPreviewMode(methodName: string) {
491	    if (this.appOptions.preview) {
492	      const error = `Calling the "${methodName}" in the preview mode is not supported.`;
493	      this.logger.error(error);
494	      throw new Error(error);
495	    }
496	  }
497	
498	  private getModulesToTriggerHooksOn(): Module[] {
499	    if (this._moduleRefsForHooksByDistance) {
500	      return this._moduleRefsForHooksByDistance;
501	    }
502	    const modulesContainer = this.container.getModules();
503	    const compareFn = (a: Module, b: Module) => b.distance - a.distance;
504	    const modulesSortedByDistance = Array.from(modulesContainer.values()).sort(
505	      compareFn,
506	    );
507	
508	    this._moduleRefsForHooksByDistance = this.appOptions?.preview
509	      ? modulesSortedByDistance.filter(moduleRef => moduleRef.initOnPreview)
510	      : modulesSortedByDistance;
511	    return this._moduleRefsForHooksByDistance;
512	  }
513	
514	  private printInPreviewModeWarning() {
515	    this.logger.warn('------------------------------------------------');
516	    this.logger.warn('Application is running in the PREVIEW mode!');
517	    this.logger.warn('Providers/controllers will not be instantiated.');
518	    this.logger.warn('------------------------------------------------');
519	  }
520	}
