42	  isUndefined,
43	} from '@nestjs/common/internal';
44	import {
45	  type CanActivate,
46	  type ClassProvider,
47	  type ExceptionFilter,
48	  type ExistingProvider,
49	  type FactoryProvider,
50	  type InjectionToken,
51	  type NestInterceptor,
52	  type PipeTransform,
53	  Scope,
54	  type Type,
55	  type ValueProvider,
56	} from '@nestjs/common';
57	
58	interface ApplicationProviderWrapper {
59	  moduleKey: string;
60	  providerKey: string;
61	  type: InjectionToken;
62	  scope?: Scope;
63	}
64	
65	interface ModulesScanParameters {
66	  moduleDefinition: ModuleDefinition;
67	  scope?: Type<unknown>[];
68	  ctxRegistry?: (ForwardReference | DynamicModule | Type<unknown>)[];
69	  overrides?: ModuleOverride[];
70	  lazy?: boolean;
71	}
72	
73	export class DependenciesScanner {
74	  private readonly applicationProvidersApplyMap: ApplicationProviderWrapper[] =
75	    [];
76	
77	  constructor(
78	    private readonly container: NestContainer,
79	    private readonly metadataScanner: MetadataScanner,
80	    private readonly graphInspector: GraphInspector,
81	    private readonly applicationConfig = new ApplicationConfig(),
82	  ) {}
83	
84	  public async scan(
85	    module: Type<any>,
86	    options?: { overrides?: ModuleOverride[] },
87	  ) {
88	    await this.registerCoreModule(options?.overrides);
89	    await this.scanForModules({
90	      moduleDefinition: module,
91	      overrides: options?.overrides,
92	    });
93	    await this.scanModulesForDependencies();
94	    this.addScopedEnhancersMetadata();
95	
96	    // Modules distance calculation should be done after all modules are scanned
97	    // but before global modules are registered (linked to all modules).
98	    // Global modules have their distance set to MAX anyway.
99	    this.calculateModulesDistance();
100	
101	    this.container.bindGlobalScope();
102	  }
103	
104	  public async scanForModules({
105	    moduleDefinition,
106	    lazy,
107	    scope = [],
108	    ctxRegistry = [],
109	    overrides = [],
110	  }: ModulesScanParameters): Promise<Module[]> {
111	    const { moduleRef: moduleInstance, inserted: moduleInserted } =
112	      (await this.insertOrOverrideModule(moduleDefinition, overrides, scope)) ??
113	      {};
114	
115	    if (lazy && !moduleInserted && moduleInstance?.isInstantiated) {
116	      return [];
117	    }
118	
119	    moduleDefinition =
120	      this.getOverrideModuleByModule(moduleDefinition, overrides)?.newModule ??
121	      moduleDefinition;
122	
123	    moduleDefinition =
124	      moduleDefinition instanceof Promise
125	        ? await moduleDefinition
126	        : moduleDefinition;
127	
128	    ctxRegistry.push(moduleDefinition);
129	
130	    if (this.isForwardReference(moduleDefinition)) {
131	      moduleDefinition = (moduleDefinition as ForwardReference).forwardRef();
132	    }
133	    const modules = !this.isDynamicModule(
134	      moduleDefinition as Type<any> | DynamicModule,
135	    )
136	      ? this.reflectMetadata(
137	          MODULE_METADATA.IMPORTS,
138	          moduleDefinition as Type<any>,
139	        )
140	      : [
141	          ...this.reflectMetadata(
142	            MODULE_METADATA.IMPORTS,
143	            (moduleDefinition as DynamicModule).module,
144	          ),
145	          ...((moduleDefinition as DynamicModule).imports || []),
146	        ];
147	
148	    let registeredModuleRefs: Module[] = [];
149	    for (const [index, innerModule] of modules.entries()) {
150	      // In case of a circular dependency (ES module system), JavaScript will resolve the type to `undefined`.
151	      if (innerModule === undefined) {
152	        throw new UndefinedModuleException(moduleDefinition, index, scope);
153	      }
154	      if (!innerModule) {
155	        throw new InvalidModuleException(
156	          moduleDefinition,
157	          index,
158	          scope,
159	          innerModule,
160	        );
161	      }
162	      if (ctxRegistry.includes(innerModule)) {
163	        continue;
164	      }
165	      const moduleRefs = await this.scanForModules({
166	        moduleDefinition: innerModule,
167	        scope: ([] as Array<Type>).concat(scope, moduleDefinition as Type),
168	        ctxRegistry,
169	        overrides,
170	        lazy,
171	      });
172	      registeredModuleRefs = registeredModuleRefs.concat(moduleRefs);
173	    }
174	    if (!moduleInstance) {
175	      return registeredModuleRefs;
176	    }
177	
178	    if (lazy) {
179	      this.container.bindGlobalsToImports(moduleInstance);
180	    }
181	    return [moduleInstance].concat(registeredModuleRefs);
182	  }
183	
184	  public async insertModule(
185	    moduleDefinition: any,
186	    scope: Type<unknown>[],
187	  ): Promise<
188	    | {
189	        moduleRef: Module;
190	        inserted: boolean;
191	      }
192	    | undefined
193	  > {
194	    const moduleToAdd = this.isForwardReference(moduleDefinition)
195	      ? moduleDefinition.forwardRef()
196	      : moduleDefinition;
197	
198	    if (this.isInjectable(moduleToAdd)) {
199	      throw new InvalidClassModuleException(
200	        moduleDefinition,
201	        scope,
202	        'provider',
203	      );
204	    }
205	    if (this.isController(moduleToAdd)) {
206	      throw new InvalidClassModuleException(
207	        moduleDefinition,
208	        scope,
209	        'controller',
210	      );
211	    }
212	    if (this.isExceptionFilter(moduleToAdd)) {
213	      throw new InvalidClassModuleException(moduleDefinition, scope, 'filter');
214	    }
215	
216	    return this.container.addModule(moduleToAdd, scope);
217	  }
218	
219	  public async scanModulesForDependencies(
220	    modules: Map<string, Module> = this.container.getModules(),
221	  ) {
222	    for (const [token, { metatype }] of modules) {
223	      await this.reflectImports(metatype, token, metatype.name);
224	      this.reflectProviders(metatype, token);
225	      this.reflectControllers(metatype, token);
226	      this.reflectExports(metatype, token);
227	    }
228	  }
229	
230	  public async reflectImports(
231	    module: Type<unknown>,
232	    token: string,
233	    context: string,
234	  ) {
235	    const modules = [
236	      ...this.reflectMetadata(MODULE_METADATA.IMPORTS, module),
237	      ...this.container.getDynamicMetadataByToken(
238	        token,
239	        MODULE_METADATA.IMPORTS as 'imports',
240	      )!,
241	    ];
242	    for (const related of modules) {
243	      await this.insertImport(related, token, context);
244	    }
245	  }
246	
247	  public reflectProviders(module: Type<any>, token: string) {
248	    const providers = [
249	      ...this.reflectMetadata(MODULE_METADATA.PROVIDERS, module),
250	      ...this.container.getDynamicMetadataByToken(
251	        token,
252	        MODULE_METADATA.PROVIDERS as 'providers',
253	      )!,
254	    ];
255	    providers.forEach(provider => {
256	      this.insertProvider(provider, token);
257	      this.reflectDynamicMetadata(provider, token);
258	    });
259	  }
260	
261	  public reflectControllers(module: Type<any>, token: string) {
262	    const controllers = [
263	      ...this.reflectMetadata(MODULE_METADATA.CONTROLLERS, module),
264	      ...this.container.getDynamicMetadataByToken(
265	        token,
266	        MODULE_METADATA.CONTROLLERS as 'controllers',
267	      )!,
268	    ];
269	    controllers.forEach(item => {
270	      this.insertController(item, token);
271	      this.reflectDynamicMetadata(item, token);
272	    });
273	  }
274	
275	  public reflectDynamicMetadata(cls: Type<Injectable>, token: string) {
276	    if (!cls || !cls.prototype) {
277	      return;
278	    }
279	    this.reflectInjectables(cls, token, GUARDS_METADATA);
280	    this.reflectInjectables(cls, token, INTERCEPTORS_METADATA);
281	    this.reflectInjectables(cls, token, EXCEPTION_FILTERS_METADATA);
282	    this.reflectInjectables(cls, token, PIPES_METADATA);
283	    this.reflectParamInjectables(cls, token, ROUTE_ARGS_METADATA);
284	  }
285	
286	  public reflectExports(module: Type<unknown>, token: string) {
287	    const exports = [
288	      ...this.reflectMetadata(MODULE_METADATA.EXPORTS, module),
289	      ...this.container.getDynamicMetadataByToken(
290	        token,
291	        MODULE_METADATA.EXPORTS as 'exports',
292	      )!,
293	    ];
294	    exports.forEach(exportedProvider =>
295	      this.insertExportedProviderOrModule(exportedProvider, token),
296	    );
297	  }
298	
299	  public reflectInjectables(
300	    component: Type<Injectable>,
301	    token: string,
302	    metadataKey: string,
303	  ) {
304	    const controllerInjectables = this.reflectMetadata<Type<Injectable>>(
305	      metadataKey,
306	      component,
307	    );
308	    const methodInjectables = this.metadataScanner
309	      .getAllMethodNames(component.prototype)
310	      .reduce(
311	        (acc, method) => {
312	          const methodInjectable = this.reflectKeyMetadata(
313	            component,
314	            metadataKey,
315	            method,
316	          );
317	
318	          if (methodInjectable) {
319	            acc.push(methodInjectable);
320	          }
321	
322	          return acc;
323	        },
324	        [] as Array<{
325	          methodKey: string;
326	          metadata: Type<Injectable>[];
327	        }>,
328	      );
329	
330	    controllerInjectables.forEach(injectable =>
331	      this.insertInjectable(
332	        injectable,
333	        token,
334	        component,
335	        ENHANCER_KEY_TO_SUBTYPE_MAP[metadataKey],
336	      ),
337	    );
338	    methodInjectables.forEach(methodInjectable => {
339	      methodInjectable.metadata.forEach(injectable =>
340	        this.insertInjectable(
341	          injectable,
342	          token,
343	          component,
344	          ENHANCER_KEY_TO_SUBTYPE_MAP[metadataKey],
345	          methodInjectable.methodKey,
346	        ),
347	      );
348	    });
349	  }
350	
351	  public reflectParamInjectables(
352	    component: Type<Injectable>,
353	    token: string,
354	    metadataKey: string,
355	  ) {
356	    const paramsMethods = this.metadataScanner.getAllMethodNames(
357	      component.prototype,
358	    );
359	
360	    paramsMethods.forEach(methodKey => {
361	      const metadata: Record<
362	        string,
363	        {
364	          index: number;
365	          data: unknown;
366	          pipes: Array<Type<PipeTransform> | PipeTransform>;
367	        }
368	      > = Reflect.getMetadata(metadataKey, component, methodKey);
369	
370	      if (!metadata) {
371	        return;
372	      }
373	
374	      const params = Object.values(metadata);
375	      params
376	        .map(item => item.pipes)
377	        .flat(1)
378	        .forEach(injectable =>
379	          this.insertInjectable(
380	            injectable,
381	            token,
382	            component,
383	            'pipe',
384	            methodKey,
385	          ),
386	        );
387	    });
388	  }
389	
390	  public reflectKeyMetadata(
391	    component: Type<Injectable>,
392	    key: string,
393	    methodKey: string,
394	  ): { methodKey: string; metadata: any } | undefined {
395	    let prototype = component.prototype;
396	    do {
397	      const descriptor = Reflect.getOwnPropertyDescriptor(prototype, methodKey);
398	      if (!descriptor) {
399	        continue;
400	      }
401	      const metadata = Reflect.getMetadata(key, descriptor.value);
402	      if (!metadata) {
403	        return;
404	      }
405	      return { methodKey, metadata };
406	    } while (
407	      (prototype = Reflect.getPrototypeOf(prototype)) &&
408	      prototype !== Object.prototype &&
409	      prototype
410	    );
411	    return undefined;
412	  }
413	
414	  public calculateModulesDistance() {
415	    const modulesGenerator = this.container.getModules().values();
416	    // Skip "InternalCoreModule"
417	    // The second element is the actual root module
418	    modulesGenerator.next();
419	
420	    const rootModule = modulesGenerator.next().value!;
421	    if (!rootModule) {
422	      return;
423	    }
424	
425	    // Convert modules to an acyclic connected graph
426	    const tree = new TopologyTree(rootModule);
427	    tree.walk((moduleRef, depth) => {
428	      if (moduleRef.isGlobal) {
429	        return;
430	      }
431	      moduleRef.distance = depth;
432	    });
433	  }
434	
435	  public async insertImport(related: any, token: string, context: string) {
436	    if (isUndefined(related)) {
437	      throw new CircularDependencyException(context);
438	    }
439	    if (this.isForwardReference(related)) {
440	      return this.container.addImport(related.forwardRef(), token);
441	    }
442	    await this.container.addImport(related, token);
443	  }
444	
445	  public isCustomProvider(
446	    provider: Provider,
447	  ): provider is
448	    | ClassProvider
449	    | ValueProvider
450	    | FactoryProvider
451	    | ExistingProvider {
452	    return provider && !isNil((provider as any).provide);
453	  }
454	
455	  public insertProvider(provider: Provider, token: string) {
456	    const isCustomProvider = this.isCustomProvider(provider);
457	    if (!isCustomProvider) {
458	      return this.container.addProvider(provider, token);
459	    }
460	    const applyProvidersMap = this.getApplyProvidersMap();
461	    const providersKeys = Object.keys(applyProvidersMap);
462	    const type = provider.provide;
463	
464	    if (!providersKeys.includes(type as string)) {
465	      return this.container.addProvider(provider as any, token);
466	    }
467	    const uuid = UuidFactory.get(type.toString());
468	    const providerToken = `${type as string} (UUID: ${uuid})`;
469	
470	    let scope = (provider as ClassProvider | FactoryProvider).scope;
471	    if (isNil(scope) && (provider as ClassProvider).useClass) {
472	      scope = getClassScope((provider as ClassProvider).useClass);
473	    }
474	    this.applicationProvidersApplyMap.push({
475	      type,
476	      moduleKey: token,
477	      providerKey: providerToken,
478	      scope,
479	    });
480	
481	    const newProvider = {
482	      ...provider,
483	      provide: providerToken,
484	      scope,
485	    } as Provider;
486	
487	    const enhancerSubtype =
488	      ENHANCER_TOKEN_TO_SUBTYPE_MAP[
489	        type as
490	          | typeof APP_GUARD
491	          | typeof APP_PIPE
492	          | typeof APP_FILTER
493	          | typeof APP_INTERCEPTOR
494	      ];
495	    const factoryOrClassProvider = newProvider as
496	      | FactoryProvider
497	      | ClassProvider;
498	    if (this.isRequestOrTransient(factoryOrClassProvider.scope!)) {
499	      return this.container.addInjectable(newProvider, token, enhancerSubtype);
500	    }
501	    this.container.addProvider(newProvider, token, enhancerSubtype);
502	  }
503	
504	  public insertInjectable(
505	    injectable: Type<Injectable> | object,
506	    token: string,
507	    host: Type<Injectable>,
508	    subtype: EnhancerSubtype,
509	    methodKey?: string,
510	  ) {
511	    if (isFunction(injectable)) {
512	      const instanceWrapper = this.container.addInjectable(
513	        injectable as Type,
514	        token,
515	        subtype,
516	        host,
517	      ) as InstanceWrapper;
518	
519	      this.graphInspector.insertEnhancerMetadataCache({
520	        moduleToken: token,
521	        classRef: host,
522	        enhancerInstanceWrapper: instanceWrapper,
523	        targetNodeId: instanceWrapper.id,
524	        subtype,
525	        methodKey,
526	      });
527	      return instanceWrapper;
528	    } else {
529	      this.graphInspector.insertEnhancerMetadataCache({
530	        moduleToken: token,
531	        classRef: host,
532	        enhancerRef: injectable,
533	        methodKey,
534	        subtype,
535	      });
536	    }
537	  }
538	
539	  public insertExportedProviderOrModule(
540	    toExport: ForwardReference | DynamicModule | Type<unknown>,
541	    token: string,
542	  ) {
543	    const fulfilledProvider = this.isForwardReference(toExport)
544	      ? toExport.forwardRef()
545	      : toExport;
546	    this.container.addExportedProviderOrModule(fulfilledProvider, token);
547	  }
548	
549	  public insertController(controller: Type<Controller>, token: string) {
550	    this.container.addController(controller, token);
551	  }
552	
553	  private insertOrOverrideModule(
554	    moduleDefinition: ModuleDefinition,
555	    overrides: ModuleOverride[],
556	    scope: Type<unknown>[],
557	  ): Promise<
558	    | {
559	        moduleRef: Module;
560	        inserted: boolean;
561	      }
562	    | undefined
563	  > {
564	    const overrideModule = this.getOverrideModuleByModule(
565	      moduleDefinition,
566	      overrides,
567	    );
568	    if (overrideModule !== undefined) {
569	      return this.overrideModule(
570	        moduleDefinition,
571	        overrideModule.newModule,
572	        scope,
573	      );
574	    }
575	
576	    return this.insertModule(moduleDefinition, scope);
577	  }
578	
579	  private getOverrideModuleByModule(
580	    module: ModuleDefinition,
581	    overrides: ModuleOverride[],
582	  ): ModuleOverride | undefined {
583	    if (this.isForwardReference(module)) {
584	      return overrides.find(moduleToOverride => {
585	        return (
586	          moduleToOverride.moduleToReplace === module.forwardRef() ||
587	          (
588	            moduleToOverride.moduleToReplace as ForwardReference
589	          ).forwardRef?.() === module.forwardRef()
590	        );
591	      });
592	    }
593	
594	    return overrides.find(
595	      moduleToOverride => moduleToOverride.moduleToReplace === module,
596	    );
597	  }
598	
599	  private async overrideModule(
600	    moduleToOverride: ModuleDefinition,
601	    newModule: ModuleDefinition,
602	    scope: Type<unknown>[],
603	  ): Promise<
604	    | {
605	        moduleRef: Module;
606	        inserted: boolean;
607	      }
608	    | undefined
609	  > {
610	    return this.container.replaceModule(
611	      this.isForwardReference(moduleToOverride)
612	        ? moduleToOverride.forwardRef()
613	        : moduleToOverride,
614	      this.isForwardReference(newModule) ? newModule.forwardRef() : newModule,
615	      scope,
616	    );
617	  }
618	
619	  public reflectMetadata<T = any>(
620	    metadataKey: string,
621	    metatype: Type<any>,
622	  ): T[] {
623	    return Reflect.getMetadata(metadataKey, metatype) || [];
624	  }
625	
626	  public async registerCoreModule(overrides?: ModuleOverride[]) {
627	    const moduleDefinition = InternalCoreModuleFactory.create(
628	      this.container,
629	      this,
630	      this.container.getModuleCompiler(),
631	      this.container.getHttpAdapterHostRef(),
632	      this.graphInspector,
633	      overrides,
634	    );
635	    const [instance] = await this.scanForModules({
636	      moduleDefinition,
637	      overrides,
638	    });
639	    this.container.registerCoreModuleRef(instance);
640	  }
641	
642	  /**
643	   * Add either request or transient globally scoped enhancers
644	   * to all controllers metadata storage
645	   */
646	  public addScopedEnhancersMetadata() {
647	    iterate(this.applicationProvidersApplyMap)
648	      .filter(wrapper => this.isRequestOrTransient(wrapper.scope!))
649	      .forEach(({ moduleKey, providerKey }) => {
650	        const modulesContainer = this.container.getModules();
651	        const { injectables } = modulesContainer.get(moduleKey)!;
652	        const instanceWrapper = injectables.get(providerKey);
653	
654	        const iterableIterator = modulesContainer.values();
655	        iterate(iterableIterator)
656	          .map(moduleRef =>
657	            Array.from<InstanceWrapper>(moduleRef.controllers.values()).concat(
658	              moduleRef.entryProviders,
659	            ),
660	          )
661	          .flatten()
662	          .forEach(controllerOrEntryProvider =>
663	            controllerOrEntryProvider.addEnhancerMetadata(instanceWrapper!),
664	          );
665	      });
666	  }
667	
668	  public applyApplicationProviders() {
669	    const applyProvidersMap = this.getApplyProvidersMap();
670	    const applyRequestProvidersMap = this.getApplyRequestProvidersMap();
671	
672	    const getInstanceWrapper = (
673	      moduleKey: string,
674	      providerKey: string,
675	      collectionKey: 'providers' | 'injectables',
676	    ) => {
677	      const modules = this.container.getModules();
678	      const collection = modules.get(moduleKey)![collectionKey];
679	      return collection.get(providerKey);
680	    };
681	
682	    // Add global enhancers to the application config
683	    this.applicationProvidersApplyMap.forEach(
684	      ({ moduleKey, providerKey, type, scope }) => {
685	        let instanceWrapper: InstanceWrapper;
686	        if (this.isRequestOrTransient(scope!)) {
687	          instanceWrapper = getInstanceWrapper(
688	            moduleKey,
689	            providerKey,
690	            'injectables',
691	          )!;
692	
693	          this.graphInspector.insertAttachedEnhancer(instanceWrapper);
694	          return applyRequestProvidersMap[type as string](instanceWrapper);
695	        }
696	        instanceWrapper = getInstanceWrapper(
697	          moduleKey,
698	          providerKey,
699	          'providers',
700	        )!;
701	        this.graphInspector.insertAttachedEnhancer(instanceWrapper);
702	        applyProvidersMap[type as string](instanceWrapper.instance);
703	      },
704	    );
705	  }
706	
707	  public getApplyProvidersMap(): { [type: string]: Function } {
708	    return {
709	      [APP_INTERCEPTOR]: (interceptor: NestInterceptor) =>
710	        this.applicationConfig.addGlobalInterceptor(interceptor),
711	      [APP_PIPE]: (pipe: PipeTransform) =>
712	        this.applicationConfig.addGlobalPipe(pipe),
713	      [APP_GUARD]: (guard: CanActivate) =>
714	        this.applicationConfig.addGlobalGuard(guard),
715	      [APP_FILTER]: (filter: ExceptionFilter) =>
716	        this.applicationConfig.addGlobalFilter(filter),
717	    };
718	  }
719	
720	  public getApplyRequestProvidersMap(): { [type: string]: Function } {
721	    return {
722	      [APP_INTERCEPTOR]: (interceptor: InstanceWrapper<NestInterceptor>) =>
723	        this.applicationConfig.addGlobalRequestInterceptor(interceptor),
724	      [APP_PIPE]: (pipe: InstanceWrapper<PipeTransform>) =>
725	        this.applicationConfig.addGlobalRequestPipe(pipe),
726	      [APP_GUARD]: (guard: InstanceWrapper<CanActivate>) =>
727	        this.applicationConfig.addGlobalRequestGuard(guard),
728	      [APP_FILTER]: (filter: InstanceWrapper<ExceptionFilter>) =>
729	        this.applicationConfig.addGlobalRequestFilter(filter),
730	    };
731	  }
732	
733	  public isDynamicModule(
734	    module: Type<any> | DynamicModule,
735	  ): module is DynamicModule {
736	    return module && !!(module as DynamicModule).module;
737	  }
738	
739	  /**
740	   * @param metatype
741	   * @returns `true` if `metatype` is annotated with the `@Injectable()` decorator.
742	   */
743	  private isInjectable(metatype: Type<any>): boolean {
744	    return !!Reflect.getMetadata(INJECTABLE_WATERMARK, metatype);
745	  }
746	
747	  /**
748	   * @param metatype
749	   * @returns `true` if `metatype` is annotated with the `@Controller()` decorator.
750	   */
751	  private isController(metatype: Type<any>): boolean {
752	    return !!Reflect.getMetadata(CONTROLLER_WATERMARK, metatype);
753	  }
754	
755	  /**
756	   * @param metatype
757	   * @returns `true` if `metatype` is annotated with the `@Catch()` decorator.
758	   */
759	  private isExceptionFilter(metatype: Type<any>): boolean {
760	    return !!Reflect.getMetadata(CATCH_WATERMARK, metatype);
761	  }
762	
763	  private isForwardReference(
764	    module: ModuleDefinition,
765	  ): module is ForwardReference {
766	    return module && !!(module as ForwardReference).forwardRef;
767	  }
768	
769	  private isRequestOrTransient(scope: Scope): boolean {
770	    return scope === Scope.REQUEST || scope === Scope.TRANSIENT;
771	  }
772	}
