1	import { Logger } from '@nestjs/common';
2	import { ExternalContextCreator } from '../../helpers/external-context-creator.js';
3	import { HttpAdapterHost } from '../../helpers/http-adapter-host.js';
4	import { GraphInspector } from '../../inspector/graph-inspector.js';
5	import { InitializeOnPreviewAllowlist } from '../../inspector/initialize-on-preview.allowlist.js';
6	import { SerializedGraph } from '../../inspector/serialized-graph.js';
7	import { ModuleOverride } from '../../interfaces/module-override.interface.js';
8	import { DependenciesScanner } from '../../scanner.js';
9	import { ModuleCompiler } from '../compiler.js';
10	import { NestContainer } from '../container.js';
