describe('lifecycle hooks after application initialization', () => {
  let events: string[];
  let loggerErrorSpy: ReturnType<typeof vitest.spyOn>;

  const record =
    (name: string) =>
    (hook: string): (() => void) =>
    () => {
      events.push(`${name}:${hook}`);
    };

  @Injectable()
  class DeepService {
    onModuleInit = record('deep', 'init')();
    onApplicationBootstrap = record('deep', 'boot')();
    onModuleDestroy = record('deep', 'destroy')();
    beforeApplicationShutdown = record('deep', 'before')();
    onApplicationShutdown = record('deep', 'shutdown')();
  }

  @Module({ providers: [DeepService], exports: [DeepService] })
  class DeepModule {}

  @Injectable()
  class ChildBService {
    onModuleInit = record('b', 'init')();
    onApplicationBootstrap = record('b', 'boot')();
    onModuleDestroy = record('b', 'destroy')();
    beforeApplicationShutdown = record('b', 'before')();
    onApplicationShutdown = record('b', 'shutdown')();
  }

  @Module({
    imports: [DeepModule],
    providers: [ChildBService],
    exports: [ChildBService],
  })
  class ChildBModule {}

  @Injectable()
  class ChildCService {
    onModuleInit = record('c', 'init')();
    onApplicationBootstrap = record('c', 'boot')();
    onModuleDestroy = record('c', 'destroy')();
    beforeApplicationShutdown = record('c', 'before')();
    onApplicationShutdown = record('c', 'shutdown')();
  }

  @Module({ providers: [ChildCService], exports: [ChildCService] })
  class ChildCModule {}

  @Injectable()
  class RootService {
    onModuleInit = record('root', 'init')();
    onApplicationBootstrap = record('root', 'boot')();
    onModuleDestroy = record('root', 'destroy')();
    beforeApplicationShutdown = record('root', 'before')();
    onApplicationShutdown = record('root', 'shutdown')();
  }

  @Module({
    imports: [ChildBModule, ChildCModule],
    providers: [RootService],
  })
  class LazyRootModule {}

  beforeEach(async () => {
    events = [];
    loggerErrorSpy = vitest
      .spyOn(Logger, 'error')
      .mockImplementation(() => undefined);

    @Module({})
    class EagerRootModule {}

    await dependenciesScanner.scan(EagerRootModule);
    await instanceLoader.createInstancesOfDependencies();
    await lazyModuleLoader.markApplicationInitialized();
  });

  afterEach(() => {
    loggerErrorSpy.mockRestore();
  });

  it('runs onModuleInit importees-first, then onApplicationBootstrap in the same order', async () => {
    await lazyModuleLoader.load(() => LazyRootModule);

    expect(events).toEqual([
      'deep:init',
      'b:init',
      'c:init',
      'root:init',
      'deep:boot',
      'b:boot',
      'c:boot',
      'root:boot',
    ]);
  });

  it('does not re-run hooks on repeated loads', async () => {
    await lazyModuleLoader.load(() => LazyRootModule);
    await lazyModuleLoader.load(() => LazyRootModule);
    await lazyModuleLoader.load(() => ({
      module: LazyRootModule,
      providers: [{ provide: 'EXTRA', useValue: 1 }],
    }));

    expect(events.filter(e => e.endsWith(':init'))).toEqual([
      'deep:init',
      'b:init',
      'c:init',
      'root:init',
    ]);
    expect(events.filter(e => e.endsWith(':boot'))).toEqual([
      'deep:boot',
      'b:boot',
      'c:boot',
      'root:boot',
    ]);
  });

